namespace HakutaiKagami.Core.Contracts;
public enum SalaryAction { Propose,Confirm,Prepare,Receive,End,CancelPrepared }
public sealed record SalaryInput(EntityId Id,SalaryAction Action,EntityId Person,EntityId Site,EntityId? Contract=null,long Amount=0,EntityId? Preparation=null);
public sealed record SalaryEntry(SalaryInput Input,long At,long Revision,bool Agreed,string Reply);
public sealed record SalaryQuote(EntityId Id,EntityId Employer,EntityId Employee,EntityId Owner,EntityId Site,long Monthly,long At,long AcceptBy,bool Agreed,string Reply);
public sealed record SalaryTerm(EntityId Id,EntityId Employer,EntityId Employee,EntityId Owner,EntityId Site,long Monthly,long[] DueAt,long? EndedAt,long Paid);
public sealed record SalaryState(int Schema,string Policy,SalaryEntry[] Entries,SalaryQuote[] Quotes,SalaryTerm[] Terms);
public sealed record SalaryCard(EntityId Id,EntityId Employer,EntityId Employee,EntityId Site,long Monthly,long Due,long Paid,long Owed,long Prepared,string Status,string? LocalResponse);
public sealed record SalaryView(EntityId Site,long PrivateRice,SalaryQuote[] Quotes,SalaryCard[] Contracts,EntityId[] People);
public static class HouseSalary
{
    public const string Policy="community-house-rice-three-month-local-consent-reliability-v4";
    const long Day=86400;
    static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool ok,string reason){if(!ok)throw new InvalidDataException(reason);}
    public static bool Enabled(ContractWorld w)=>w.NewGame?.EconomyPolicy is Policy or VillageConsultation.Policy or NpcCommunityAdministration.Policy or CommunityStewardship.Policy or MaterialMarkets.Policy or RegionalDomains.Policy;
    static bool Before(SalaryEntry e,long at,long rev)=>e.At<at||e.At==at&&e.Revision<rev;
    static SalaryEntry[] Prefix(ContractWorld w,long at,long rev)=>w.Salary?.Entries.Where(e=>Before(e,at,rev)).ToArray()??[];
    public static bool OwnIdUsed(ContractWorld w,EntityId id)=>w.Salary?.Entries.Any(e=>e.Input.Id==id)==true;
    static bool Local(ContractWorld w,EntityId person,EntityId site,long at,long rev)=>w.Characters.Any(c=>c.Id==person&&c.Life==LifeState.Adult)&&TransportWork.At(w,person,site,at,rev,stableCompletion:true);
    static (EntityId Head,EntityId Employee,EntityId Owner) Parties(ContractWorld w,EntityId other,EntityId site,long at,long rev)
    {
        var f=w.NewGame!.Start.Factions.SingleOrDefault(f=>f.Home==site.Value||NewGameWorld.Node(f.Home)==NewGameWorld.Node(site.Value));Need(f!=null,"現地の支給契約を持つ家がありません");var head=new EntityId(f.Head);var employee=head==w.PlayerControl?other:w.PlayerControl;Need(head==other||head==w.PlayerControl,"主君と家臣の当事者ではありません");Need(head!=employee&&w.ServiceBonds.Any(b=>b.Subject==employee&&b.Target==head&&b.From<=at&&(at<b.Until||at==b.Until&&rev<b.Revision)),"直属関係を確認できません");var owner=new EntityId(f.Id);Authority(w,head,owner,site,at,rev);return(head,employee,owner);
    }
    static void Authority(ContractWorld w,EntityId head,EntityId owner,EntityId site,long at,long rev)=>Need(FactionStances.ResolveAuthority(w,head,owner,at,rev)!=null&&w.LandRights.Any(r=>r.Subject==owner&&r.Target==site&&r.Kind=="control"&&r.From<=at&&at<r.Until),"家の蔵の処分権がありません");
    static long Due(SalaryTerm t,long at)=>checked(t.Monthly*t.DueAt.Count(d=>d<=at&&(t.EndedAt==null||d<=t.EndedAt)));
    static SalaryEntry? Prepared(SalaryEntry[] es,EntityId term,long at,long rev)=>es.LastOrDefault(e=>e.Input.Action==SalaryAction.Prepare&&e.Input.Contract==term&&Before(e,at,rev)&&at<=e.At+Day&&!es.Any(x=>Before(x,at,rev)&&(x.Input.Action==SalaryAction.Receive||x.Input.Action==SalaryAction.CancelPrepared)&&x.Input.Preparation==e.Input.Id)&&!es.Any(x=>Before(x,at,rev)&&x.Input.Action==SalaryAction.End&&x.Input.Contract==term&&x.Revision>e.Revision));
    internal static long Reserved(ContractWorld w,EntityId site,long at,long rev){var es=Prefix(w,at,rev);return es.Where(e=>e.Input.Action==SalaryAction.Confirm).Select(e=>e.Input.Contract!.Value).Distinct().Select(id=>Prepared(es,id,at,rev)).Where(e=>e!=null&&e.Input.Site==site).Sum(e=>e!.Input.Amount);}
    internal static (long At,long Revision,long Amount)[] Payouts(ContractWorld w,EntityId site,long until,long revision)=>w.Salary?.Entries.Where(e=>e.Input.Action==SalaryAction.Receive&&e.Input.Site==site&&e.At<=until&&e.Revision<=revision).Select(e=>(e.At,e.Revision,w.Salary.Entries.Single(p=>p.Input.Id==e.Input.Preparation).Input.Amount)).ToArray()??[];
    internal static long Received(ContractWorld w,EntityId employee,long at,long rev){var es=Prefix(w,at,rev);return es.Where(e=>e.Input.Action==SalaryAction.Receive).Where(e=>{var q=es.Single(q=>q.Input.Id==e.Input.Contract);var employer=w.NewGame!.Start.Factions.Single(f=>NewGameWorld.Node(f.Home)==NewGameWorld.Node(q.Input.Site.Value)).Head;return employee.Value==(employer==w.PlayerControl.Value?q.Input.Person.Value:w.PlayerControl.Value);}).Sum(e=>es.Single(p=>p.Input.Id==e.Input.Preparation).Input.Amount);}
    public static long PrivateRice(ContractWorld w,EntityId employee,long at=long.MaxValue,long rev=long.MaxValue)=>Received(w,employee,at,rev)-RegionalTrade.SalaryLoaded(w,employee,at,rev);
    static int Reliability(ContractWorld w,IEnumerable<SalaryTerm> terms,EntityId employee,EntityId owner,long at,long rev)
    {
        int score=70;var es=Prefix(w,at,rev);foreach(var t in terms.Where(t=>t.Employee==employee&&t.Owner==owner)){int n=0;foreach(var due in t.DueAt.Where(d=>d<=at&&(t.EndedAt==null||d<=t.EndedAt))){n++;long paid=es.Where(e=>e.Input.Action==SalaryAction.Receive&&e.Input.Contract==t.Id&&e.At<=due+Day).Sum(e=>es.Single(p=>p.Input.Id==e.Input.Preparation).Input.Amount);if(at>due+Day&&paid<t.Monthly*n)score-=15;else if(paid>=t.Monthly*n)score+=3;}score-=checked((int)Math.Min(30,(Math.Max(0,Due(t,at)-t.Paid)+t.Monthly-1)/t.Monthly*10));}return Math.Clamp(score,0,100);
    }
    static SalaryState Replay(ContractWorld w,SalaryEntry[] es,long until,long revision)
    {
        var quotes=new Dictionary<EntityId,SalaryQuote>();var terms=new Dictionary<EntityId,SalaryTerm>();var ids=new HashSet<EntityId>();long previous=0,previousAt=0;
        foreach(var e in es){var i=e.Input;Need(e.Revision>previous&&e.Revision<=revision&&e.At>=previousAt&&e.At<=until&&EntityId.IsValid(i.Id.Value)&&ids.Add(i.Id)&&Enum.IsDefined(i.Action)&&CommunityEconomy.SitesFor(w).Contains(i.Site)&&i.Person!=w.PlayerControl,"支給原本の順序・対象が不正です");Need(!FactionStances.OtherIdUsed(w,i.Id,includeSalary:false)&&!FactionStances.OwnIdUsed(w,i.Id),"別の操作に使った原本IDです");Need(Local(w,w.PlayerControl,i.Site,e.At,e.Revision)&&Local(w,i.Person,i.Site,e.At,e.Revision),"当事者が現地で会っていません");
            if(i.Action==SalaryAction.Propose){Need(i.Contract==null&&i.Preparation==null&&i.Amount>=1&&i.Amount<=200,"希望額は1〜200kg/月です");var p=Parties(w,i.Person,i.Site,e.At,e.Revision);Need(!terms.Values.Any(t=>t.Employee==p.Employee&&t.Owner==p.Owner&&t.EndedAt==null&&t.DueAt[^1]>=e.At),"先に現在の給付約束の期間を終えてください");long owed=terms.Values.Where(t=>t.Employee==p.Employee&&t.Owner==p.Owner).Sum(t=>Due(t,e.At)-t.Paid);int trust=Reliability(w,terms.Values,p.Employee,p.Owner,e.At,e.Revision);bool agreed=i.Amount>=20&&(p.Head==w.PlayerControl||i.Amount<=40)&&owed==0&&(p.Head!=w.PlayerControl||trust>=40);string reply=owed>0?"以前の未払いを先に精算しましょう。":p.Head==w.PlayerControl&&trust<40?"支給が遅れた記録があるため、新しい約束は今は受けられません。":!agreed?"その月額では約束できません。":"この月額で月初三回、現地で将来分の終了を通知できる条件に同意します。過去の未払いは残ります。";Need(e.Agreed==agreed&&e.Reply==reply,"相手の返答原本が一致しません");quotes.Add(i.Id,new(i.Id,p.Head,p.Employee,p.Owner,i.Site,i.Amount,e.At,e.At+Day,agreed,reply));}
            else{Need(i.Contract is {} id&&quotes.ContainsKey(id)&&i.Preparation==null==(i.Action is not(SalaryAction.Receive or SalaryAction.CancelPrepared)),"給付原本との対応が不正です");var q=quotes[i.Contract!.Value];Need(i.Site==q.Site&&i.Person==(q.Employer==w.PlayerControl?q.Employee:q.Employer)&&!e.Agreed&&e.Reply=="", "当事者や確認原本が違います");Authority(w,q.Employer,q.Owner,q.Site,e.At,e.Revision);
                if(i.Action==SalaryAction.Confirm){Need(i.Amount==0&&q.Agreed&&e.At<=q.AcceptBy&&!terms.ContainsKey(q.Id),"有効な同じ返答を確認してください");Need(!terms.Values.Any(t=>t.Employee==q.Employee&&t.Owner==q.Owner&&t.EndedAt==null&&t.DueAt[^1]>=e.At),"Another active salary promise exists");var parties=Parties(w,i.Person,i.Site,e.At,e.Revision);Need(parties.Head==q.Employer&&parties.Employee==q.Employee,"直属関係が変わりました");var epoch=DateOnly.Parse(w.EpochDate);var date=epoch.AddDays(checked((int)(e.At/Day)));var next=new DateOnly(date.Year,date.Month,1).AddMonths(1);var dues=Enumerable.Range(0,3).Select(n=>(next.AddMonths(n).DayNumber-epoch.DayNumber)*Day).ToArray();terms.Add(q.Id,new(q.Id,q.Employer,q.Employee,q.Owner,q.Site,q.Monthly,dues,null,0));}
                else{Need(terms.TryGetValue(q.Id,out var t),"成立済みの給付契約ではありません");long owed=Due(t!,e.At)-t!.Paid;switch(i.Action){
                    case SalaryAction.Prepare:Need(i.Amount>0&&i.Amount<=owed&&Prepared(es,q.Id,e.At,e.Revision)==null,"未払い額と既存の支払引当を確認してください");var account=CommunityEconomy.AccountAt(w,i.Site,e.At,e.Revision);Need(i.Amount<=account.HouseRice-Reserved(w,i.Site,e.At,e.Revision),"家の自由米が不足しています。未払い分は残ります。");break;
                    case SalaryAction.Receive:var ready=Prepared(es,q.Id,e.At,e.Revision);Need(i.Amount==0&&ready!=null&&ready.Input.Id==i.Preparation&&ready.Input.Amount<=owed,"現地で用意された同じ米を受け取ってください");terms[q.Id]=t with{Paid=checked(t.Paid+ready.Input.Amount)};break;
                    case SalaryAction.CancelPrepared:Need(i.Amount==0&&Prepared(es,q.Id,e.At,e.Revision)?.Input.Id==i.Preparation,"有効な支払準備ではありません");break;
                    case SalaryAction.End:Need(i.Amount==0&&t.EndedAt==null,"既に終了した給付約束です");terms[q.Id]=t with{EndedAt=e.At};break;
                    default:throw new InvalidDataException("未対応の給付操作です");
                }}
            }previous=e.Revision;previousAt=e.At;
        }foreach(var t in terms.Values)Need(t.Paid<=Due(t,until),"給付債務以上を支払っています");foreach(var person in w.Characters)Need(PrivateRice(w,person.Id,until,revision+1)>=0,"受領米を二重に処分しています");return new(1,Policy,es,quotes.Values.ToArray(),terms.Values.ToArray());
    }
    internal static void Initialize(ContractWorld w){if(Enabled(w))w.Salary=Replay(w,[],w.ElapsedSeconds,w.CommitSequence);}
    internal static void Tick(ContractWorld w){if(Enabled(w))w.Salary=Replay(w,w.Salary!.Entries,w.ElapsedSeconds,w.CommitSequence);}
    internal static void Apply(ContractWorld w,SalaryInput i){bool agreed=false;string reply="";if(i.Action==SalaryAction.Propose){var p=Parties(w,i.Person,i.Site,w.ElapsedSeconds,w.CommitSequence);long owed=w.Salary!.Terms.Where(t=>t.Employee==p.Employee&&t.Owner==p.Owner).Sum(t=>Due(t,w.ElapsedSeconds)-t.Paid);int trust=Reliability(w,w.Salary.Terms,p.Employee,p.Owner,w.ElapsedSeconds,w.CommitSequence);agreed=i.Amount>=20&&(p.Head==w.PlayerControl||i.Amount<=40)&&owed==0&&(p.Head!=w.PlayerControl||trust>=40);reply=owed>0?"以前の未払いを先に精算しましょう。":p.Head==w.PlayerControl&&trust<40?"支給が遅れた記録があるため、新しい約束は今は受けられません。":!agreed?"その月額では約束できません。":"この月額で月初三回、現地で将来分の終了を通知できる条件に同意します。過去の未払いは残ります。";}w.Salary=w.Salary! with{Entries=[..w.Salary.Entries,new(i,w.ElapsedSeconds,w.CommitSequence,agreed,reply)]};Tick(w);}
    internal static void Validate(ContractWorld w){if(!Enabled(w)){Need(w.Salary==null,"旧保存へ給付契約を混在できません");return;}Need(w.Salary is {Schema:1,Policy:Policy,Entries:not null,Terms:not null,Quotes:not null},"給付契約の版が不正です");Need(ContractJson.CanonicalHash(w.Salary)==ContractJson.CanonicalHash(Replay(w,w.Salary.Entries,w.ElapsedSeconds,w.CommitSequence)),"給付原本と債務・受領が一致しません");}
    internal static long? NextBoundary(ContractWorld w,long target)=>w.Salary?.Terms.SelectMany(t=>t.DueAt.Where(d=>t.EndedAt==null||d<=t.EndedAt)).Concat(w.Salary.Entries.Where(e=>e.Input.Action==SalaryAction.Prepare).Select(e=>e.At+Day+1)).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().Select(t=>(long?)t).FirstOrDefault();
    internal static SalaryView? View(ContractWorld w){if(!Enabled(w))return null;var site=w.Locations.Single(l=>l.Actor==w.PlayerControl).Site;if(site==null||!CommunityEconomy.SitesFor(w).Contains(site.Value)||!Local(w,w.PlayerControl,site.Value,w.ElapsedSeconds,w.CommitSequence+1))return null;var es=w.Salary!.Entries;var cards=w.Salary.Terms.Select(t=>{long due=Due(t,w.ElapsedSeconds);bool near=Local(w,t.Employee==w.PlayerControl?t.Employer:t.Employee,t.Site,w.ElapsedSeconds,w.CommitSequence+1)&&site==t.Site;int trust=Reliability(w,w.Salary.Terms,t.Employee,t.Owner,w.ElapsedSeconds,w.CommitSequence+1);string? comment=t.Employee==w.PlayerControl?trust<40?"支給が遅れた履歴があります。継続するかは本人が判断します。":due>t.Paid?"未払いの給付があります。":"受領済みの給付を確認しています。":near?trust<40?"度重なる遅配で、新しい給付約束には慎重です。":due>t.Paid?"未払い分の支給を待っています。":"受領済みの給付を確認しています。":null;return new SalaryCard(t.Id,t.Employer,t.Employee,t.Site,t.Monthly,due,t.Paid,due-t.Paid,Prepared(es,t.Id,w.ElapsedSeconds,w.CommitSequence+1)?.Input.Amount??0,t.EndedAt!=null?"終了・過去の未払いは保持":w.ElapsedSeconds>t.DueAt[^1]?"三回分の期間終了":"月初の給付約束",comment);}).ToArray();var people=w.Characters.Where(c=>c.Id!=w.PlayerControl&&Local(w,c.Id,site.Value,w.ElapsedSeconds,w.CommitSequence+1)).Where(c=>{try{Parties(w,c.Id,site.Value,w.ElapsedSeconds,w.CommitSequence);return true;}catch(InvalidDataException){return false;}}).Select(c=>c.Id).ToArray();return new(site.Value,PrivateRice(w,w.PlayerControl),w.Salary.Quotes,cards,people);}
}
public sealed partial class WorldSession
{
    public SalaryView? SalaryView(){lock(gate)return HouseSalary.View(state);}
    public CommandResult ManageSalary(SalaryInput input,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||!HouseSalary.Enabled(state))return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,"本人の給付相談ではありません");var old=state.Salary!.Entries.SingleOrDefault(e=>e.Input.Id==input.Id);if(old!=null)return new(old.Input==input?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"処理済みの給付操作です");if(FactionStances.OtherIdUsed(state,input.Id)||FactionStances.OwnIdUsed(state,input.Id))return new(ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"別操作の原本IDです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,input.Id,state.CommitSequence,"条件を読み直してください");try{Change(w=>HouseSalary.Apply(w,input));return new(ResultCode.Accepted,input.Id,state.CommitSequence,"給付原本へ記録しました");}catch(Exception e)when(e is InvalidDataException or ArgumentException or InvalidOperationException or OverflowException){return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,e.Message);}}}
}
